final class ContextSignedWitnessSecondMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static final class Fixture {
  final ContextSignedWitnessContinuationScope.Receipt scope;final ContextSignedWitnessNextReceiver.Result next;
  Fixture(boolean reverse,boolean already)throws Exception{
   Snapshot x=ContextSignedWitnessReceiverMatrix.bind(true,"!anchor(1); !@u ~global(u); !@x start(x)&&a(x)->mid(x); !@x mid(x)&&b(x)->~end(x);"+(already?" !~end(1);":""));Snapshot a=ContextSignedWitnessReceiverMatrix.bind(false,"!start(1); !a(1); !$u aa(u)&&~aside(u);"),b=ContextSignedWitnessReceiverMatrix.bind(false,"!b(1); !$u bb(u)&&~bside(u);");List<Snapshot> fs=reverse?Arrays.asList(b,a):Arrays.asList(a,b);ContextSignedWitnessFrameAudit.Receipt seeds=ContextSignedWitnessReceiverMatrix.frame(x,fs);ContextUniversalFrozenBranch.Limits limits=ContextSignedWitnessReceiverMatrix.limits(16,WORK);ContextSignedWitnessInitialEntry.Result initial=ContextSignedWitnessInitialEntry.assemble(seeds,64,limits,WORK,64);require(initial.status==ContextSignedWitnessInitialEntry.Status.READY,initial.reason);ContextSignedWitnessInitialEntry.Receipt receipt=ContextSignedWitnessInitialEntry.inspect(initial.entry,seeds,64,limits,WORK,64);scope=ContextSignedWitnessNextMatrix.scope(receipt,seeds,limits);next=ContextSignedWitnessNextReceiver.run(scope,64,limits,WORK);require(next.status==ContextSignedWitnessNextReceiver.Status.CHECKED,next.phase+": "+next.reason);
  }
 }
 static ContextSignedWitnessSuccessorBarrier.Result run(ContextSignedWitnessNextReceiver.Result next,ContextSignedWitnessContinuationScope.Receipt scope){ContextSignedWitnessSuccessorBarrier.Result r=ContextSignedWitnessSuccessorBarrier.run(next,scope,64,scope.limits,WORK,64);require(r.merged,r.phase+": "+r.reason);return r;}
 static void audit(ContextSignedWitnessSuccessorBarrier.Result r,ContextSignedWitnessContinuationScope.Receipt s){ContextSignedWitnessSuccessorBarrierAudit.Receipt a=ContextSignedWitnessSuccessorBarrierAudit.inspect(r,r.next,s,64,s.limits,WORK,64);ContextSignedWitnessSuccessorBarrierAudit.check(a,r.next,s,64,s.limits,WORK,1);require(true,"direct second-barrier/carrier audit capacity1");}
 static void positive()throws Exception{
  for(boolean reverse:new boolean[]{false,true})for(boolean already:new boolean[]{false,true}){Fixture f=new Fixture(reverse,already);ConstraintBarrier first=f.scope.barrier.result.barrier;require(first.packet.items.stream().anyMatch(i->i.atom.predicate.equals("mid")),"first barrier contains A-derived mid");require(first.packet.items.stream().filter(i->i.atom.predicate.equals("end")).allMatch(i->i.proofs.stream().allMatch(p->p.sources.size()==1)),"five-source terminal proof absent before successor transport");ContextSignedWitnessSuccessorBarrier.Result r=run(f.next,f.scope);Item end=r.barrier.packet.items.stream().filter(i->i.atom.predicate.equals("end")).findFirst().orElseThrow(()->new AssertionError("missing second-barrier end"));require(!end.atom.positive&&end.proofs.stream().anyMatch(p->p.sources.size()==5&&p.sources.stream().filter(s->s.localX).count()==2),"second barrier exports signed end with TWO X rules+A start+A a+B b Sources");require(r.barrier.changed,"new Source alternative is a real common change");if(already){require(first.packet.items.size()==r.barrier.packet.items.size(),"grade-only case has unchanged atom count");require(end.proofs.stream().anyMatch(p->p.sources.size()==1&&p.depth==0)&&end.proofs.stream().anyMatch(p->p.sources.size()==5),"original singleton and new alternative both retained");}else require(r.barrier.packet.items.size()>first.packet.items.size(),"new terminal atom becomes shared only at second barrier");
   for(Map.Entry<Cut,PrivatePool> e:r.barrier.privatePools.entrySet()){require(e.getValue().common==r.barrier.packet&&e.getValue().signedSeeds==f.scope.seeds,"second private frame retains original seed scope");require(ContextWitnessResultTransport.retains(first.privatePools.get(e.getKey()).local,e.getValue().local,ContextGroundProductionRounds.budget(WORK)),"ALL prior private proof alternatives retained");}
   require(r.units.prior.checks.equals(f.next.checks)&&r.compounds.prior.checks.equals(f.next.checks)&&r.units.prior!=f.scope.barrier.result.units&&r.compounds.prior!=f.scope.barrier.result.compounds,"carriers freshly collected from successor owners, not reused initial inventory");audit(r,f.scope);
   Snapshot target=f.scope.seeds.frame.plan.foreign.get(0);ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspectSignedContinuation(f.scope,target,64,WORK,WORK);ContextUniversalFrozenConstraints.Result later=ContextUniversalFrozenConstraints.closeSignedCompounds(rows,r.barrier.packet,r.barrier.privatePools.get(Cut.of(target)),r.units,r.compounds,16,16,512,256,WORK);require(!later.closed,"first-successor scope cannot authorize second-successor frame");
  }
  for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessBarrierMatrix.Fixture f=new ContextSignedWitnessBarrierMatrix.Fixture(true,reverse);ContextSignedWitnessContinuationScope.Receipt s=ContextSignedWitnessNextMatrix.scope(f.initial,f.frame,f.limits);ContextSignedWitnessNextReceiver.Result next=ContextSignedWitnessNextReceiver.run(s,64,s.limits,WORK);require(next.status==ContextSignedWitnessNextReceiver.Status.CHECKED,next.reason);ContextSignedWitnessSuccessorBarrier.Result r=run(next,s);require(r.barrier.privatePools.size()==1&&r.barrier.branches.size()==2,"trusted group remains one logical private cut");audit(r,s);}
  System.out.println("SIGNED_WITNESS_SECOND chainedOrders=4 trustedOrders=2 newFiveSourceSignedProduct=true unchangedAtomCountStillChanged=true exactFreshCarriers=true privateRetention=true directAudit=true laterGuarded=true");
 }
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessSuccessorBarrier.Result r,String why){require(!r.merged&&r.next==null&&r.barrier==null&&r.units==null&&r.compounds==null,why+": no prefix");}
 static void boundaries()throws Exception{
  Fixture f=new Fixture(false,false);ContextSignedWitnessSuccessorBarrier.Result r=run(f.next,f.scope);ContextSignedWitnessSuccessorBarrierAudit.Receipt receipt=ContextSignedWitnessSuccessorBarrierAudit.inspect(r,f.next,f.scope,64,f.scope.limits,WORK,64);
  incomplete(ContextSignedWitnessSuccessorBarrier.run(f.next,f.scope,64,f.scope.limits,1,64),"fresh successor audit budget");incomplete(ContextSignedWitnessSuccessorBarrier.run(f.next,f.scope,63,f.scope.limits,WORK,64),"exact row policy");incomplete(ContextSignedWitnessSuccessorBarrier.run(f.next,f.scope,64,f.scope.limits,WORK,0),"capacity bound");reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,1,64),"receipt freshly audits current budget");
  Object saved=ContextSignedWitnessBarrierMatrix.replace(r.barrier,"branches",Collections.emptyMap());reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64),"lost donor cut");ContextSignedWitnessBarrierMatrix.replace(r.barrier,"branches",saved);
  saved=ContextSignedWitnessBarrierMatrix.replace(r,"units",f.scope.barrier.result.units);reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64),"old carrier cannot stand in for successor collection");ContextSignedWitnessBarrierMatrix.replace(r,"units",saved);
  saved=ContextSignedWitnessBarrierMatrix.replace(r.barrier,"changed",false);reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64),"wrong actual change flag");ContextSignedWitnessBarrierMatrix.replace(r.barrier,"changed",saved);
  List<Item> dropped=new ArrayList<>(r.barrier.packet.items);dropped.removeIf(i->i.atom.predicate.equals("end"));saved=ContextSignedWitnessBarrierMatrix.replace(r.barrier.packet,"items",Collections.unmodifiableList(dropped));reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64),"isolated second-packet product drop");ContextSignedWitnessBarrierMatrix.replace(r.barrier.packet,"items",saved);
  saved=ContextSignedWitnessBarrierMatrix.replace(f.scope.barrier.result.barrier,"privatePools",Collections.emptyMap());incomplete(ContextSignedWitnessSuccessorBarrier.run(f.next,f.scope,64,f.scope.limits,WORK,64),"historical cut loss poisons continuation");reject(()->ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64),"historical loss invalidates old second-barrier receipt");ContextSignedWitnessBarrierMatrix.replace(f.scope.barrier.result.barrier,"privatePools",saved);ContextSignedWitnessSuccessorBarrierAudit.check(receipt,f.next,f.scope,64,f.scope.limits,WORK,64);require(true,"restored full historical graph passes");
  Map<Cut,ConstraintTransfer> missing=new LinkedHashMap<>(r.barrier.branches);missing.remove(missing.keySet().iterator().next());ConstraintBarrier bad=ContextWitnessResultTransport.mergeSignedWitnessSuccessor(f.next,missing,WORK);require(!bad.merged&&bad.packet==null&&bad.privatePools.isEmpty()&&bad.branches.isEmpty(),"adapter rejects missing cut before any prefix");
  System.out.println("SIGNED_WITNESS_SECOND_BOUNDARIES budgetsPolicyNoPrefixes=true actualDonorCarrierProductGradeAndHistoryReplayed=true laterScopeUnchanged=true noAdmission=true");
 }
}
